"""Survey versioned-document filenames across sibling git repositories.

For each tracked .md file under a <lang>/docs/ directory, read the version
from front matter (sat:version, dcterms:version or version) and compare it
with the filename postfix. Prints one tab-separated line per finding.
"""
import re
import subprocess
import sys
from pathlib import Path

BASE = Path(sys.argv[1])
HYPH = re.compile(r"-v(\d+)-(\d+)-(\d+)(-[a-z]+)?$")
DOT = re.compile(r"-v(\d+)\.(\d+)\.(\d+)$")
FIELD = re.compile(r'^(sat:version|dcterms:version|version):\s*"?v?([0-9][^"\s]*)"?\s*$')


def front_version(path):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (UnicodeDecodeError, OSError):
        return None, None
    if not lines or lines[0].strip() != "---":
        return None, None
    for line in lines[1:80]:
        if line.strip() == "---":
            break
        m = FIELD.match(line)
        if m:
            return m.group(1), m.group(2)
    return None, None


for repo in sorted(p for p in BASE.iterdir() if (p / ".git").exists()):
    files = subprocess.run(["git", "-C", str(repo), "ls-files"],
                           capture_output=True, text=True).stdout.splitlines()
    for rel in files:
        if not rel.endswith(".md") or "/docs/" not in "/" + rel:
            continue
        if "tests/fixtures/" in rel or "node_modules/" in rel:
            continue
        stem = Path(rel).name[:-3]
        field, ver = front_version(repo / rel)
        h, d = HYPH.search(stem), DOT.search(stem)
        name_ver = None
        if h:
            name_ver = ".".join(h.group(1, 2, 3))
            kind = "hyphenated" + (h.group(4) or "")
        elif d:
            name_ver = ".".join(d.groups())
            kind = "dotted"
        else:
            kind = "none"
        major = None
        if ver and re.match(r"\d+\.\d+\.\d+$", ver):
            major = int(ver.split(".")[0])
        notes = []
        if kind.startswith("hyphenated"):
            notes.append("HYPHENATED")
        if ver and name_ver and ver != name_ver:
            notes.append(f"MISMATCH name={name_ver} fm={ver}")
        if major is not None and major >= 1 and kind != "none":
            notes.append("POSTFIX_AT_1+")
        if major is not None and major < 1 and kind == "none":
            notes.append("MISSING_POSTFIX")
        if notes:
            print(f"{repo.name}\t{rel}\t{field}={ver}\t{' '.join(notes)}")

"""Find references to hyphenated-version filenames across sibling repositories.

Prints repo, file, line number, category, field-or-context and the matched
name, tab-separated. Categories: frontmatter, link, history, manifest,
state, code, inline.
"""
import re
import subprocess
import sys
from pathlib import Path

BASE = Path(sys.argv[1])
NAME = re.compile(r"[A-Za-z0-9_.-]*-v\d+-\d+-\d+(?:-draft)?(?:\.(?:md|pdf))?")
GIT_STATUS = re.compile(r"^\s*(new file|renamed|deleted|modified|R|A|M|D)\s*:?\s")
LINK = re.compile(r"\]\(([^)]*)\)")
HISTORY_HEADING = re.compile(r"^#{1,6}\s.*(changelog|history|release notes)", re.I)
TEXT_EXT = {".md", ".py", ".yaml", ".yml", ".toml", ".txt", ".js", ".mjs",
            ".json", ".njk", ".sh", ".gitignore", ".cfg", ".html", ""}

for repo in sorted(p for p in BASE.iterdir() if (p / ".git").exists()):
    files = subprocess.run(["git", "-C", str(repo), "ls-files"],
                           capture_output=True, text=True).stdout.splitlines()
    for rel in files:
        p = Path(rel)
        if p.suffix not in TEXT_EXT or rel.startswith(("node_modules/", "data/")):
            continue
        try:
            lines = (repo / rel).read_text(encoding="utf-8").splitlines()
        except (UnicodeDecodeError, OSError, IsADirectoryError):
            continue
        in_fm = bool(lines) and lines[0].strip() == "---"
        field = ""
        in_history = False
        for no, line in enumerate(lines, 1):
            if in_fm and no > 1 and line.strip() == "---":
                in_fm = False
                continue
            if in_fm:
                m = re.match(r"^([A-Za-z:_]+):", line)
                if m:
                    field = m.group(1)
            elif line.startswith("#"):
                in_history = bool(HISTORY_HEADING.match(line))
            for m in NAME.finditer(line):
                name = m.group(0)
                if p.name == "CHANGELOG.md" or GIT_STATUS.match(line) or in_history:
                    cat, ctx = "history", ""
                elif p.name.startswith("ff-manifest"):
                    cat, ctx = "manifest", ""
                elif p.name == ".file-fairy-state.yaml":
                    cat, ctx = "state", ""
                elif in_fm:
                    cat, ctx = "frontmatter", field
                elif any(name in t for t in LINK.findall(line)):
                    cat, ctx = "link", ""
                elif p.suffix != ".md":
                    cat, ctx = "code", p.suffix
                else:
                    cat, ctx = "inline", ""
                print(f"{repo.name}\t{rel}\t{no}\t{cat}\t{ctx}\t{name}")

