"""List relative Markdown links that resolve at one commit but not at another.

Usage: brokenlinks.py REPO OLD_REV NEW_REV
Prints file:line and the link target for every link in NEW_REV whose
target is missing in NEW_REV, and marks whether it already broke in OLD_REV.
"""
import re
import subprocess
import sys
from pathlib import PurePosixPath

repo, old, new = sys.argv[1:4]
LINK = re.compile(r"\]\(([^)\s#]+)(?:#[^)]*)?\)")


def files(rev):
    out = subprocess.run(["git", "-C", repo, "ls-tree", "-r", "--name-only", rev],
                         capture_output=True, text=True, check=True).stdout
    return set(out.splitlines())


def broken(rev, tree):
    found = set()
    for rel in sorted(f for f in tree if f.endswith(".md")):
        text = subprocess.run(["git", "-C", repo, "show", f"{rev}:{rel}"],
                              capture_output=True, text=True, errors="replace").stdout
        for no, line in enumerate(text.splitlines(), 1):
            for target in LINK.findall(line):
                if re.match(r"^[a-z]+:", target) or target.startswith("/"):
                    continue
                path = PurePosixPath(rel).parent / target
                parts = []
                for p in path.parts:
                    if p == "..":
                        if parts:
                            parts.pop()
                    elif p != ".":
                        parts.append(p)
                norm = "/".join(parts)
                if norm not in tree and not any(f.startswith(norm + "/") for f in tree):
                    found.add((rel, target))
    return found


old_broken = broken(old, files(old))
for rel, target in sorted(broken(new, files(new))):
    if (rel, target) not in old_broken:
        print(f"NEW  {rel} -> {target}")
